import React, { useState, useEffect } from 'react';
import { vendorAPI, apiCall } from '../../services/apiService';
import './VendorApplications.css';

const VendorApplications = () => {
  const [applications, setApplications] = useState([]);
  const [profile, setProfile] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isCreating, setIsCreating] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    setError('');

    // Fetch both profile and applications
    const [profileResult, appsResult] = await Promise.all([
      apiCall(vendorAPI.getProfile),
      apiCall(vendorAPI.getApplications)
    ]);

    if (profileResult.success) {
      setProfile(profileResult.data);
    }

    if (appsResult.success) {
      setApplications(appsResult.data || []);
    } else {
      setError(appsResult.error);
    }

    setIsLoading(false);
  };

  const handleCreateApplication = async () => {
    setIsCreating(true);
    setError('');
    setSuccess('');

    const result = await apiCall(vendorAPI.createApplication);

    if (result.success) {
      setSuccess('Application created successfully!');
      fetchData(); // Refresh the list
    } else {
      setError(result.error);
    }

    setIsCreating(false);
  };

  const handleSubmitApplication = async (applicationId) => {
    const result = await apiCall(vendorAPI.submitApplication, applicationId);

    if (result.success) {
      setSuccess('Application submitted for review!');
      fetchData(); // Refresh the list
    } else {
      setError(result.error);
    }
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading applications...
      </div>
    );
  }

  const canCreateApplication = profile && profile.profileComplete;
  const hasApplications = applications.length > 0;

  return (
    <div className="vendor-applications">
      <div className="page-header">
        <div className="container">
          <h1>License Applications</h1>
          <p>Manage your food truck license applications</p>
        </div>
      </div>

      <div className="container">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        {success && (
          <div className="alert alert-success">
            {success}
          </div>
        )}

        {/* Profile Check */}
        {!canCreateApplication && (
          <div className="profile-warning">
            <div className="warning-icon">!</div>
            <div className="warning-content">
              <h3>Complete Your Profile First</h3>
              <p>You need to complete your vendor profile before you can create license applications.</p>
              <a href="/vendor/profile" className="btn btn-primary">
                Complete Profile
              </a>
            </div>
          </div>
        )}

        {/* Applications Summary */}
        <div className="applications-summary">
          <div className="summary-stats">
            <div className="stat-item">
              <div className="stat-number">{applications.length}</div>
              <div className="stat-label">Total Applications</div>
            </div>
            
            <div className="stat-item">
              <div className="stat-number">
                {applications.filter(app => 
                  app.status === 'SUBMITTED' || app.status === 'UNDER_REVIEW'
                ).length}
              </div>
              <div className="stat-label">Under Review</div>
            </div>
            
            <div className="stat-item">
              <div className="stat-number">
                {applications.filter(app => app.status === 'APPROVED').length}
              </div>
              <div className="stat-label">Approved</div>
            </div>
          </div>

          {canCreateApplication && (
            <div className="create-application">
              <button
                onClick={handleCreateApplication}
                className="btn btn-primary"
                disabled={isCreating}
              >
                {isCreating ? (
                  <>
                    <span className="loading-spinner"></span>
                    Creating...
                  </>
                ) : (
                  'Create New Application'
                )}
              </button>
            </div>
          )}
        </div>

        {/* Applications List */}
        {!hasApplications ? (
          <div className="no-applications">
            <div className="no-app-icon">📄</div>
            <h3>No Applications Yet</h3>
            {canCreateApplication ? (
              <p>Ready to apply for your food truck license? Create your first application to get started.</p>
            ) : (
              <p>Complete your profile first, then you can create license applications.</p>
            )}
          </div>
        ) : (
          <div className="applications-list">
            {applications.map(application => (
              <ApplicationCard
                key={application.id}
                application={application}
                onSubmit={handleSubmitApplication}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const ApplicationCard = ({ application, onSubmit }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);

  const getStatusInfo = (status) => {
    const statusMap = {
      DRAFT: { label: 'Draft', color: 'pending', description: 'Application created but not submitted' },
      SUBMITTED: { label: 'Submitted', color: 'submitted', description: 'Waiting for admin review' },
      UNDER_REVIEW: { label: 'Under Review', color: 'submitted', description: 'Being reviewed by admin' },
      APPROVED: { label: 'Approved', color: 'approved', description: 'Application approved' },
      REJECTED: { label: 'Rejected', color: 'rejected', description: 'Application rejected' },
      INSPECTION_SCHEDULED: { label: 'Inspection Scheduled', color: 'submitted', description: 'Inspection has been scheduled' },
      INSPECTION_COMPLETED: { label: 'Inspection Completed', color: 'submitted', description: 'Inspection completed, awaiting results' },
      LICENSED: { label: 'Licensed', color: 'approved', description: 'License issued successfully' }
    };
    return statusMap[status] || { label: status, color: 'pending', description: 'Unknown status' };
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Not available';
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    await onSubmit(application.id);
    setIsSubmitting(false);
  };

  const statusInfo = getStatusInfo(application.status);
  const canSubmit = application.status === 'DRAFT';

  return (
    <div className="application-card">
      <div className="app-header">
        <div className="app-id">
          <h3>Application #{application.id}</h3>
          <span className={`status-badge ${statusInfo.color}`}>
            {statusInfo.label}
          </span>
        </div>
        <div className="app-actions">
          {canSubmit && (
            <button
              onClick={handleSubmit}
              className="btn btn-primary btn-sm"
              disabled={isSubmitting}
            >
              {isSubmitting ? (
                <>
                  <span className="loading-spinner"></span>
                  Submitting...
                </>
              ) : (
                'Submit Application'
              )}
            </button>
          )}
        </div>
      </div>

      <div className="app-body">
        <div className="app-status">
          <div className="status-description">
            {statusInfo.description}
          </div>
        </div>

        <div className="app-details">
          <div className="detail-grid">
            <div className="detail-item">
              <span className="detail-label">Created:</span>
              <span className="detail-value">{formatDate(application.createdAt)}</span>
            </div>

            {application.submittedAt && (
              <div className="detail-item">
                <span className="detail-label">Submitted:</span>
                <span className="detail-value">{formatDate(application.submittedAt)}</span>
              </div>
            )}

            {application.reviewedAt && (
              <div className="detail-item">
                <span className="detail-label">Reviewed:</span>
                <span className="detail-value">{formatDate(application.reviewedAt)}</span>
              </div>
            )}

            {application.comments && (
              <div className="detail-item full-width">
                <span className="detail-label">Comments:</span>
                <span className="detail-value">{application.comments}</span>
              </div>
            )}
          </div>
        </div>

        {canSubmit && (
          <div className="app-footer">
            <div className="submit-notice">
              <strong>Ready to submit?</strong> Once submitted, you cannot modify this application.
              It will be reviewed by our admin team.
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default VendorApplications;
